//! Arithmetic in GF(2^16) as PAR2 2.0 defines it: the field generated by 2 under the
//! polynomial x^16 + x^12 + x^3 + x + 1 (0x1100B), and the matrices repair inverts.

use std::sync::OnceLock;

/// Nonzero elements of the field; 2 generates all of them.
const ORDER: usize = 65535;
/// The most input slices a recovery set can hold: one per power of 2 whose exponent is
/// coprime to 65535 (= 3 * 5 * 17 * 257).
pub(crate) const MAX_INPUTS: usize = 32768;

struct Tables {
    /// `log[x]` for nonzero `x`, so that `2^log[x] = x`. `log[0]` is unused.
    log: Vec<u16>,
    /// `exp[i] = 2^i`, twice over so that a sum of two logs needs no reduction.
    exp: Vec<u16>,
    /// The exponent of each input slice's constant, in slice order.
    inputs: Vec<u16>,
}

fn tables() -> &'static Tables {
    static TABLES: OnceLock<Tables> = OnceLock::new();
    TABLES.get_or_init(|| {
        let mut log = vec![0u16; ORDER + 1];
        let mut exp = vec![0u16; 2 * ORDER];
        let mut x: u32 = 1;
        for i in 0..ORDER {
            exp[i] = x as u16;
            exp[i + ORDER] = x as u16;
            log[x as usize] = i as u16;
            x <<= 1;
            if x & 0x1_0000 != 0 {
                x ^= 0x1_100B;
            }
        }
        let inputs = (1..ORDER as u16).filter(|n| n % 3 != 0 && n % 5 != 0 && n % 17 != 0 && n % 257 != 0).collect();
        Tables { log, exp, inputs }
    })
}

/// `a * b`.
pub(crate) fn mul(a: u16, b: u16) -> u16 {
    if a == 0 || b == 0 {
        return 0;
    }
    let t = tables();
    t.exp[usize::from(t.log[usize::from(a)]) + usize::from(t.log[usize::from(b)])]
}

/// `1 / a`, for nonzero `a`; 0 for 0, which has no inverse.
pub(crate) fn inv(a: u16) -> u16 {
    if a == 0 {
        return 0;
    }
    let t = tables();
    t.exp[ORDER - usize::from(t.log[usize::from(a)])]
}

/// The coefficient of input slice `index` in the recovery slice of `exponent`: the slice's
/// constant raised to the exponent. None past the last input slice a set can hold.
pub(crate) fn coefficient(index: usize, exponent: u16) -> Option<u16> {
    let t = tables();
    let n = *t.inputs.get(index)?;
    Some(t.exp[(usize::from(n) * usize::from(exponent)) % ORDER])
}

/// A square matrix over the field, row-major.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct Matrix {
    pub(crate) size: usize,
    pub(crate) cells: Vec<u16>,
}

impl Matrix {
    pub(crate) fn get(&self, row: usize, col: usize) -> u16 {
        self.cells[row * self.size + col]
    }

    /// The inverse, by Gauss-Jordan elimination, or None when the matrix is singular.
    pub(crate) fn inverse(&self) -> Option<Matrix> {
        let n = self.size;
        let mut a = self.cells.clone();
        let mut b = vec![0u16; n * n];
        for i in 0..n {
            b[i * n + i] = 1;
        }
        for col in 0..n {
            let pivot = (col..n).find(|&r| a[r * n + col] != 0)?;
            if pivot != col {
                for k in 0..n {
                    a.swap(pivot * n + k, col * n + k);
                    b.swap(pivot * n + k, col * n + k);
                }
            }
            let scale = inv(a[col * n + col]);
            for k in 0..n {
                a[col * n + k] = mul(a[col * n + k], scale);
                b[col * n + k] = mul(b[col * n + k], scale);
            }
            for r in 0..n {
                let f = a[r * n + col];
                if r == col || f == 0 {
                    continue;
                }
                for k in 0..n {
                    a[r * n + k] ^= mul(f, a[col * n + k]);
                    b[r * n + k] ^= mul(f, b[col * n + k]);
                }
            }
        }
        Some(Matrix { size: n, cells: b })
    }
}

/// Picks rows of `candidates` (each `inputs.len()` long), in order, until `inputs.len()` of
/// them are linearly independent, and returns their positions and the inverse of the square
/// matrix they form. None when the candidates span fewer dimensions than that.
pub(crate) fn independent_rows(candidates: &[Vec<u16>], size: usize) -> Option<(Vec<usize>, Matrix)> {
    if size == 0 {
        return Some((Vec::new(), Matrix { size: 0, cells: Vec::new() }));
    }
    // Rows reduced against the ones before them, each with its leading column scaled to 1.
    let mut basis: Vec<(usize, Vec<u16>)> = Vec::new();
    let mut chosen = Vec::new();
    for (i, row) in candidates.iter().enumerate() {
        let mut r = row.clone();
        r.resize(size, 0);
        for (lead, b) in &basis {
            let f = r[*lead];
            if f != 0 {
                for (x, y) in r.iter_mut().zip(b) {
                    *x ^= mul(f, *y);
                }
            }
        }
        let Some(lead) = r.iter().position(|&x| x != 0) else { continue };
        let scale = inv(r[lead]);
        for x in &mut r {
            *x = mul(*x, scale);
        }
        basis.push((lead, r));
        chosen.push(i);
        if chosen.len() == size {
            break;
        }
    }
    if chosen.len() < size {
        return None;
    }
    let mut cells = Vec::with_capacity(size * size);
    for &i in &chosen {
        cells.extend(candidates[i].iter().copied().chain(std::iter::repeat(0)).take(size));
    }
    let inverse = Matrix { size, cells }.inverse()?;
    Some((chosen, inverse))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_field_is_a_field() {
        // 2 generates every nonzero element exactly once.
        let t = tables();
        let mut seen = vec![false; ORDER + 1];
        for &x in &t.exp[..ORDER] {
            assert!(!seen[usize::from(x)] && x != 0);
            seen[usize::from(x)] = true;
        }
        for a in [1u16, 2, 3, 0x100B, 0x8000, 0xffff] {
            assert_eq!(mul(a, inv(a)), 1);
            assert_eq!(mul(a, 1), a);
            assert_eq!(mul(a, 0), 0);
        }
        // Reduction by the PAR2 polynomial: x^15 * x = x^16 = x^12 + x^3 + x + 1.
        assert_eq!(mul(0x8000, 2), 0x100B);
    }

    #[test]
    fn input_constants_follow_the_spec() {
        let t = tables();
        assert_eq!(t.inputs.len(), MAX_INPUTS);
        // The first exponents skip multiples of 3 and 5: 1, 2, 4, 7, 8, 11, ...
        assert_eq!(&t.inputs[..6], &[1, 2, 4, 7, 8, 11]);
        assert_eq!(coefficient(0, 1), Some(2));
        assert_eq!(coefficient(2, 1), Some(16));
        assert_eq!(coefficient(5, 0), Some(1));
        assert_eq!(coefficient(MAX_INPUTS, 1), None);
    }

    #[test]
    #[allow(clippy::needless_range_loop)]
    fn inverse_undoes_the_matrix() {
        let rows: Vec<Vec<u16>> = (0..5u16).map(|e| (0..4).map(|i| coefficient(i, e).unwrap()).collect()).collect();
        // Exponent 0 gives a row of ones, independent of the rest.
        let (chosen, inverse) = independent_rows(&rows, 4).unwrap();
        assert_eq!(chosen, [0, 1, 2, 3]);
        for i in 0..4 {
            for j in 0..4 {
                let dot = (0..4).fold(0, |acc, k| acc ^ mul(inverse.get(i, k), rows[chosen[k]][j]));
                assert_eq!(dot, u16::from(i == j));
            }
        }
    }

    #[test]
    fn dependent_rows_are_skipped() {
        let rows = vec![vec![1, 1], vec![1, 1], vec![1, 2]];
        let (chosen, _) = independent_rows(&rows, 2).unwrap();
        assert_eq!(chosen, [0, 2]);
        assert!(independent_rows(&rows[..2], 2).is_none());
    }
}
